const lessons=[{"sentences":[{"speaker":"A","text":"What time will the hotel restaurant begin serving breakfast this morning.","role":"question","position":1,"audioStartSeconds":0,"audioEndSeconds":4.631291666666667},{"speaker":"B","text":"They start at six o clock every day.","role":"choice","position":2,"audioStartSeconds":5.331291666666667,"audioEndSeconds":8.338875},{"speaker":"B","text":"Eggs and toast sound delicious right now.","role":"choice","position":3,"audioStartSeconds":8.538875,"audioEndSeconds":11.59375},{"speaker":"B","text":"It is located on the second floor near the elevator.","role":"choice","position":4,"audioStartSeconds":11.79375,"audioEndSeconds":15.737083333333333},{"speaker":"A","text":"Where should we leave our heavy luggage before checking in.","role":"question","position":5,"audioStartSeconds":20.737083333333334,"audioEndSeconds":24.320333333333334},{"speaker":"B","text":"No thank you I can carry it myself.","role":"choice","position":6,"audioStartSeconds":25.020333333333333,"audioEndSeconds":28.164625},{"speaker":"B","text":"The front desk staff can store it for you.","role":"choice","position":7,"audioStartSeconds":28.364625,"audioEndSeconds":31.457416666666667},{"speaker":"B","text":"We already checked out yesterday morning.","role":"choice","position":8,"audioStartSeconds":31.657416666666666,"audioEndSeconds":34.763083333333334},{"speaker":"A","text":"How often does the free airport shuttle bus depart from here.","role":"question","position":9,"audioStartSeconds":39.763083333333334,"audioEndSeconds":43.75791666666667},{"speaker":"B","text":"Flight number four hundred arrives around noon.","role":"choice","position":10,"audioStartSeconds":44.45791666666667,"audioEndSeconds":47.795541666666665},{"speaker":"B","text":"It leaves every thirty minutes throughout the afternoon.","role":"choice","position":11,"audioStartSeconds":47.99554166666667,"audioEndSeconds":51.65533333333333},{"speaker":"B","text":"Yes the ticket costs twenty dollars online.","role":"choice","position":12,"audioStartSeconds":51.855333333333334,"audioEndSeconds":55.41204166666667},{"speaker":"A","text":"When will our hotel room be ready for us.","role":"question","position":13,"audioStartSeconds":60.41204166666667,"audioEndSeconds":63.53575},{"speaker":"B","text":"Housekeeping should finish cleaning it by two o clock.","role":"choice","position":14,"audioStartSeconds":64.23575,"audioEndSeconds":67.88266666666667},{"speaker":"B","text":"We booked a double room with a view.","role":"choice","position":15,"audioStartSeconds":68.08266666666667,"audioEndSeconds":70.76308333333333},{"speaker":"B","text":"They stayed at that resort last summer.","role":"choice","position":16,"audioStartSeconds":70.96308333333333,"audioEndSeconds":73.9705}],"questions":[{"prompt":"Choose the best response to question one","options":["They start at six o clock every day.","Eggs and toast sound delicious right now.","It is located on the second floor near the elevator."],"answer":"A","evidenceSentence":1,"evidence":"What time will the hotel restaurant begin serving breakfast this morning","explanation":"Câu hỏi bắt đầu bằng \"What time\" (Mấy giờ), nên câu trả lời thích hợp nhất là chỉ thời gian (\"They start at six o clock every day\")."},{"prompt":"Choose the best response to question two","options":["No thank you I can carry it myself.","The front desk staff can store it for you.","We already checked out yesterday morning."],"answer":"B","evidenceSentence":5,"evidence":"Where should we leave our heavy luggage before checking in","explanation":"Câu hỏi hỏi về địa điểm cất hành lý (\"Where should we leave our heavy luggage\"), do đó câu trả lời đưa ra gợi ý về nơi cất đồ là phù hợp nhất."},{"prompt":"Choose the best response to question three","options":["Flight number four hundred arrives around noon.","It leaves every thirty minutes throughout the afternoon.","Yes the ticket costs twenty dollars online."],"answer":"B","evidenceSentence":9,"evidence":"How often does the free airport shuttle bus depart from here","explanation":"Câu hỏi \"How often\" (Bao lâu một lần) yêu cầu câu trả lời chỉ tần suất hoặc chu kỳ thời gian của chuyến xe buýt."},{"prompt":"Choose the best response to question four","options":["Housekeeping should finish cleaning it by two o clock.","We booked a double room with a view.","They stayed at that resort last summer."],"answer":"A","evidenceSentence":13,"evidence":"When will our hotel room be ready for us","explanation":"Câu hỏi \"When\" (Khi nào) hỏi về thời gian phòng khách sạn sẵn sàng, và câu trả lời đưa ra mốc thời gian dọn phòng xong."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
